/// <summary>
/// Extension of modifiedField method
/// </summary>
/// <param name = "_fieldId">FieldId</param>
public void modifiedField(FieldId _fieldId)
{
    next modifiedField(_fieldId);

    switch (_fieldId)
    {
        case fieldNum(CredManCreditLimitCustGroup, AVARiscDebtor) :
            if (!this.AVACompanyId)
            {
                this.AVACompanyId = curExt();
            }
            //if (!this.CustLineExists(this.AVARiscDebtor))
            if (!this.CustLineExists(this.AVARiscDebtor, this.AVACompanyId))
            {
                this.CreditLimitId  = this.AVACompanyId + this.AVARiscDebtor;
                this.Description    = CustTable::find(this.AVARiscDebtor).name();
            }
            break;

    }
}

/// <summary>
/// returns if CustLine exists
/// </summary>
/// <param name = "_riscDebtor">CustAccount</param>
/// <param name = "_companyId">AVACompanyId</param>
/// <returns>boolean</returns>
//private boolean CustLineExists(CustAccount  _riscDebtor)
private boolean CustLineExists(CustAccount  _riscDebtor, AVACompanyId   _companyId)
{
    boolean                             ret = false;
    CredManCreditLimitCustGroupLine     crlCustGroupLine;
    CredManCreditLimitCustGroup         crlCustGroup;

    //select firstonly CreditLimitCustGroup from crlCustGroupLine where  crlCustGroupLine.CustAccount == _riscDebtor;
    select firstonly CreditLimitCustGroup from crlCustGroupLine where  crlCustGroupLine.CustAccount == _riscDebtor
                    join crlCustGroup where crlCustGroup.RecId == crlCustGroupLine.CreditLimitCustGroup
                                         && crlCustGroup.AVACompanyId  == _companyId;

    if (crlCustGroupLine.CreditLimitCustGroup)
    {
        warning(strFmt("@NDX:NXACRLGroupLineExists", crlCustGroupLine.CreditLimitCustGroup));
        ret = true;
    }
    return ret;
}
